'use strict';
// Builds dsp/ (Rust) to WebAssembly and embeds it in web/ladder-wasm.js for the AudioWorklet.
// The generated file is committed, so running the app never needs a Rust toolchain.
const {spawnSync} = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const dsp = path.join(root, 'dsp');
// SIMD lets the oversampling FIRs vectorize; every supported Chrome and Electron has it.
const result = spawnSync('cargo', ['build', '--release', '--target', 'wasm32-unknown-unknown'], {
  cwd: dsp,
  stdio: 'inherit',
  env: {...process.env, RUSTFLAGS: '-C target-feature=+simd128'},
});
if (result.error || result.status !== 0) {
  console.error('Install Rust and run: rustup target add wasm32-unknown-unknown');
  process.exit(result.status || 1);
}
const wasm = fs.readFileSync(path.join(dsp, 'target/wasm32-unknown-unknown/release/afterhours_dsp.wasm'));
fs.writeFileSync(
  path.join(root, 'web/ladder-wasm.js'),
  `'use strict';\n// Generated by scripts/build-dsp.cjs from dsp/. Do not edit.\nglobalThis.AfterhoursLadderWasm = '${wasm.toString('base64')}';\n`,
);
console.log(`web/ladder-wasm.js · ${wasm.length} bytes of WebAssembly`);
